<?php

declare(strict_types=1);
session_start(); header('Content-Type: application/json; charset=utf-8'); require_once __DIR__ . '/../../../config/database.php';
$userId = (int) ($_SESSION['user_id'] ?? 0); if ($userId < 1) { http_response_code(401); echo json_encode(['error' => 'Authentification requise.']); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'GET') { $peerId = filter_input(INPUT_GET, 'user_id', FILTER_VALIDATE_INT); if ($peerId) { $statement = $pdo->prepare("SELECT m.id, m.sender_id, m.recipient_id, m.body, m.read_at, m.created_at, CASE WHEN m.sender_id = :current_user THEN 'me' ELSE 'peer' END AS sender FROM messages m WHERE (m.sender_id = :current_user_messages AND m.recipient_id = :peer_id) OR (m.sender_id = :peer_messages AND m.recipient_id = :current_user_recipient) ORDER BY m.created_at ASC"); $statement->execute(['current_user' => $userId, 'current_user_messages' => $userId, 'peer_id' => $peerId, 'peer_messages' => $peerId, 'current_user_recipient' => $userId]); $pdo->prepare('UPDATE messages SET read_at = NOW() WHERE recipient_id = :recipient_id AND sender_id = :sender_id AND read_at IS NULL')->execute(['recipient_id' => $userId, 'sender_id' => $peerId]); echo json_encode(['success' => true, 'data' => $statement->fetchAll()]); exit; } $statement = $pdo->prepare("SELECT peer.id AS user_id, CONCAT(peer.first_name, ' ', peer.last_name) AS name, peer.role, ap.id AS artisan_id, latest.body AS last_message, latest.created_at AS last_message_time, SUM(CASE WHEN unread.read_at IS NULL AND unread.recipient_id = :unread_user THEN 1 ELSE 0 END) AS unread_count FROM (SELECT DISTINCT CASE WHEN sender_id = :sender_user THEN recipient_id ELSE sender_id END AS peer_id FROM messages WHERE sender_id = :sender_messages OR recipient_id = :recipient_messages) peers INNER JOIN users peer ON peer.id = peers.peer_id LEFT JOIN artisan_profiles ap ON ap.user_id = peer.id LEFT JOIN messages latest ON latest.id = (SELECT MAX(m2.id) FROM messages m2 WHERE (m2.sender_id = :latest_sender AND m2.recipient_id = peer.id) OR (m2.sender_id = peer.id AND m2.recipient_id = :latest_recipient)) LEFT JOIN messages unread ON (unread.sender_id = peer.id AND unread.recipient_id = :unread_recipient) GROUP BY peer.id, peer.first_name, peer.last_name, peer.role, ap.id, latest.body, latest.created_at ORDER BY latest.created_at DESC"); $statement->execute(['sender_user' => $userId, 'sender_messages' => $userId, 'recipient_messages' => $userId, 'unread_user' => $userId, 'latest_sender' => $userId, 'latest_recipient' => $userId, 'unread_recipient' => $userId]); $conversations = array_map(static function (array $conversation): array { return ['id' => (int) $conversation['user_id'], 'userId' => (int) $conversation['user_id'], 'artisanId' => $conversation['artisan_id'] ? (int) $conversation['artisan_id'] : null, 'artisanName' => $conversation['name'], 'artisanAvatar' => 'https://via.placeholder.com/50/C2652A/FFFFFF?text=' . rawurlencode(substr($conversation['name'], 0, 1)), 'lastMessage' => $conversation['last_message'] ?? '', 'lastMessageTime' => $conversation['last_message_time'], 'unread' => (int) $conversation['unread_count'] > 0, 'online' => false]; }, $statement->fetchAll()); echo json_encode(['success' => true, 'data' => $conversations]); exit; }
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); header('Allow: GET, POST'); echo json_encode(['error' => 'Méthode non autorisée.']); exit; } $input = json_decode(file_get_contents('php://input'), true); $body = trim((string) ($input['body'] ?? '')); $recipientUserId = filter_var($input['recipientUserId'] ?? null, FILTER_VALIDATE_INT); $artisanId = filter_var($input['artisanId'] ?? null, FILTER_VALIDATE_INT); if (!$recipientUserId && $artisanId) { $recipient = $pdo->prepare("SELECT user_id FROM artisan_profiles WHERE id = :artisan_id AND verification_status = 'verified' LIMIT 1"); $recipient->execute(['artisan_id' => $artisanId]); $recipientUserId = (int) $recipient->fetchColumn(); } if (!$recipientUserId || $recipientUserId === $userId || $body === '' || mb_strlen($body) > 5000) { http_response_code(422); echo json_encode(['error' => 'Destinataire ou message invalide.']); exit; } $recipientCheck = $pdo->prepare('SELECT id FROM users WHERE id = :id AND is_active = 1 LIMIT 1'); $recipientCheck->execute(['id' => $recipientUserId]); if (!$recipientCheck->fetch()) { http_response_code(404); echo json_encode(['error' => 'Destinataire introuvable.']); exit; } $statement = $pdo->prepare('INSERT INTO messages (sender_id, recipient_id, body, order_id, quote_id) VALUES (:sender_id, :recipient_id, :body, :order_id, :quote_id)'); $statement->execute(['sender_id' => $userId, 'recipient_id' => $recipientUserId, 'body' => $body, 'order_id' => filter_var($input['orderId'] ?? null, FILTER_VALIDATE_INT) ?: null, 'quote_id' => filter_var($input['quoteId'] ?? null, FILTER_VALIDATE_INT) ?: null]); echo json_encode(['success' => true, 'message' => 'Message envoyé.', 'id' => (int) $pdo->lastInsertId()]);
